public int[] SearchRange(int[] nums, int target)
{
    return new[] { FindBound(nums, target, true), FindBound(nums, target, false) };
}

private int FindBound(int[] nums, int target, bool findFirst)
{
    int left = 0, right = nums.Length - 1, bound = -1;
    while (left <= right)
    {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target)
        {
            bound = mid;
            if (findFirst) right = mid - 1;   // keep going left
            else left = mid + 1;              // keep going right
        }
        else if (nums[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return bound;
}

